import { Component, Env, h, State } from '@stencil/core';

@Component({
  tag: 'g33-showcase',
  styleUrl: 'g33-showcase.css',
  shadow: true,
})
export class G33Showcase {
  @State() hero: any;

  async componentWillLoad() {
    const token = Env.STORYBLOK_TOKEN;
    const response = await fetch(`https://api.storyblok.com/v2/cdn/stories/home?version=draft&token=${token}`);
    const data = await response.json();

    this.hero = data.story.content.body.find(block => block.component === 'HeroBanner');
  }

  render() {
    return (
      <main>
        <h1>G33 Design System</h1>

        <p class="intro">
          Web Components library built with Stencil, consumed without framework-specific code by a{' '}
          <a href="https://g33-react-consumer.vercel.app/" target="_blank" rel="noopener noreferrer">
            React app
          </a>{' '}
          and an{' '}
          <a href="https://g33-angular-consumer.vercel.app/" target="_blank" rel="noopener noreferrer">
            Angular app
          </a>
          .
        </p>

        <section>
          <h2>Buttons</h2>

          <div class="demo-row">
            <g33-button size="sm">Petit</g33-button>
            <g33-button size="md">Moyen</g33-button>
            <g33-button size="lg">Grand</g33-button>
          </div>

          <div class="demo-row">
            <g33-button variant="secondary">Secondaire</g33-button>
            <g33-button variant="secondary" disabled>
              Désactivé
            </g33-button>
          </div>
        </section>

        <section>
          <h2>Alerts</h2>

          <g33-alert type="success">Article publié avec succès</g33-alert>

          <g33-alert type="warning">Article en cours d'édition</g33-alert>

          <g33-alert type="error">Article supprimé</g33-alert>
        </section>

        <section>
          <h2>Content card</h2>

          <g33-content-card
            contentTitle="Christophe Dugarry : « On a un président, un actionnaire, qui est transparent. Il n’y a rien d’humain dans ce club. »"
            category="Médias"
            excerpt="Dans l’émission Rothen s’enflamme (RMC), Christophe Dugarry a donné son avis sur le sujet Cannes, Bordeaux, les clubs historiques sont-ils..."
            imageUrl="https://admin.girondins33.com/storage/2024/02/logo-girondins-bordeaux-sc-1-800x445.webp"
            author="Julien"
            publishedAt="27 février 2025"
            publishedDateTime="2025-02-27"
            contentUrl="https://www.girondins33.com/Actualites/72512-christophe-dugarry-on-a-un-president-un-actionnaire-qui-est-transparent-il-ny-a-rien-dhumain-dans-ce-club"
          ></g33-content-card>
        </section>

        <section>
          <h2>Content List Item</h2>

          <g33-content-list-item
            contentTitle="Christophe Dugarry : « On a un président, un actionnaire, qui est transparent. Il n’y a rien d’humain dans ce club. »"
            category="Médias"
            displayDate="27/02"
            publishedDateTime="2025-02-27"
            contentUrl="https://www.girondins33.com/Actualites/72512-christophe-dugarry-on-a-un-president-un-actionnaire-qui-est-transparent-il-ny-a-rien-dhumain-dans-ce-club"
          ></g33-content-list-item>
        </section>

        {this.hero && (
          <section>
            <h2>Hero Banner / Storyblok</h2>

            <h3>Simple</h3>
            <g33-hero-banner titleText={this.hero.titleText} imageUrl={this.hero.image?.filename} />

            <h3>Avec sous-titre</h3>
            <g33-hero-banner titleText={this.hero.titleText} subtitle={this.hero.subtitle} imageUrl={this.hero.image?.filename} />

            <h3>Complet</h3>
            <g33-hero-banner
              titleText={this.hero.titleText}
              subtitle={this.hero.subtitle}
              imageUrl={this.hero.image?.filename}
              imageAlt={this.hero.image?.alt}
              ctaLabel={this.hero.ctaLabel}
              ctaUrl={this.hero.ctaUrl?.url || '#'}
              ctaTarget={this.hero.ctaUrl?.target}
            />
          </section>
        )}
      </main>
    );
  }
}
